            @foreach(($initialPolling['packages'] ?? []) as $package)
            <article class="package package-tone-{{ ($package['number'] - 1) % 4 }}" data-package-id="{{ $package['id'] }}"><span class="package-watermark" aria-hidden="true"></span><header class="package-head"><span class="package-number">{{ $package['number'] }}</span><div class="package-title"><small>Paket Kandidat</small><strong>{{ $package['name'] }}</strong><em>{{ $package['slogan'] ?: 'Bersama untuk madrasah' }}</em></div><span class="rank-badge" data-rank>#{{ $loop->iteration }}</span></header><div class="candidates" style="--candidate-columns:{{ count($package['candidates']) }}">
                @foreach($package['candidates'] as $candidate)<div class="candidate"><div class="portrait"><img src="{{ $candidate['photo'] }}" alt="Foto {{ $candidate['name'] }}"></div><small>{{ $candidate['role'] }}</small><strong title="{{ $candidate['name'] }}">{{ $candidate['name'] }}</strong><span class="candidate-class">{{ $candidate['class'] }}</span><span class="candidate-vote" data-candidate-votes>{{ number_format($package['votes'], 0, ',', '.') }} suara paket</span></div>@endforeach
            </div><footer class="result"><div class="result-value"><span>Statistik perolehan</span><strong><b data-votes data-value="{{ $package['votes'] }}">{{ number_format($package['votes'], 0, ',', '.') }}</b><small data-percentage>{{ $package['percentage'] }}%</small></strong></div><div class="bar {{ $package['votes'] > 0 ? 'has-value' : '' }}"><span data-bar style="width:{{ $package['percentage'] }}%"></span></div></footer></article>
            @endforeach
        </section>
        <footer class="footer"><span>Perolehan ditampilkan secara agregat. Identitas pemilih tidak pernah dipublikasikan.</span><span><strong>LIVE POLLING OSIS</strong> · MAN 1 Metro</span></footer>
    </div>
</main>
<script>
const dataUrl=@json(route('public.osis-polling.data'));let phase=@json($initialPolling['phase'] ?? null);let startsAt=@json($initialPolling['starts_at'] ?? null);let endsAt=@json($initialPolling['ends_at'] ?? null);let requestRunning=false;
const formatNumber=value=>new Intl.NumberFormat('id-ID').format(Number(value||0));
const escapeHtml=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[char]));
function setMode(active){document.getElementById('emptyState').hidden=active;document.getElementById('pollingState').hidden=!active;document.getElementById('liveStatus').classList.toggle('offline',!active);document.getElementById('liveLabel').textContent=active?(phase==='paused'?'DIJEDA':(phase==='scheduled'?'MENUNGGU':'LIVE')):'STANDBY'}
function renderPackages(packages){const grid=document.getElementById('packageGrid');grid.dataset.count=packages.length;grid.style.setProperty('--columns',Math.min(Math.max(packages.length,1),6));grid.innerHTML=packages.map((item,index)=>{const tone=((Math.abs(Number(item.number)||1)-1)%4);return `<article class="package package-tone-${tone}" data-package-id="${escapeHtml(item.id)}"><span class="package-watermark" aria-hidden="true"></span><header class="package-head"><span class="package-number">${escapeHtml(item.number)}</span><div class="package-title"><small>Paket Kandidat</small><strong>${escapeHtml(item.name)}</strong><em>${escapeHtml(item.slogan||'Bersama untuk madrasah')}</em></div><span class="rank-badge" data-rank>#${index+1}</span></header><div class="candidates" style="--candidate-columns:${Math.max(item.candidates.length,1)}">${item.candidates.map(candidate=>`<div class="candidate"><div class="portrait"><img src="${escapeHtml(candidate.photo)}" alt="Foto ${escapeHtml(candidate.name)}"></div><small>${escapeHtml(candidate.role)}</small><strong title="${escapeHtml(candidate.name)}">${escapeHtml(candidate.name)}</strong><span class="candidate-class">${escapeHtml(candidate.class)}</span><span class="candidate-vote" data-candidate-votes>${formatNumber(item.votes)} suara paket</span></div>`).join('')}</div><footer class="result"><div class="result-value"><span>Statistik perolehan</span><strong><b data-votes data-value="${Number(item.votes)||0}">${formatNumber(item.votes)}</b><small data-percentage>${escapeHtml(item.percentage)}%</small></strong></div><div class="bar ${Number(item.votes)>0?'has-value':''}"><span data-bar style="width:${Number(item.percentage)||0}%"></span></div></footer></article>`}).join('')}
function reorderPackages(packages){const grid=document.getElementById('packageGrid'),cards=[...grid.querySelectorAll('[data-package-id]')],before=new Map(cards.map(card=>[card.dataset.packageId,card.getBoundingClientRect()])),ranked=[...packages].sort((a,b)=>Number(b.votes)-Number(a.votes)||Number(a.number)-Number(b.number));ranked.forEach((item,index)=>{const card=grid.querySelector(`[data-package-id="${item.id}"]`);if(!card)return;card.querySelector('[data-rank]').textContent='#'+(index+1);card.classList.toggle('is-leading',index===0&&Number(item.votes)>0);grid.appendChild(card)});requestAnimationFrame(()=>cards.forEach(card=>{const first=before.get(card.dataset.packageId),last=card.getBoundingClientRect();if(!first)return;const x=first.left-last.left,y=first.top-last.top;if(x||y)card.animate?.([{transform:`translate(${x}px,${y}px)`,zIndex:4},{transform:'translate(0,0)',zIndex:1}],{duration:720,easing:'cubic-bezier(.2,.8,.2,1)'})}))}
function updatePolling(data){phase=data.phase;startsAt=data.starts_at;endsAt=data.ends_at;setMode(data.active);document.getElementById('updatedAt').textContent=data.updated_at||'--:--:--';if(!data.active)return;document.getElementById('electionTitle').textContent=data.title;document.getElementById('electionTheme').textContent=data.theme||'Pilihan hari ini, langkah baik untuk madrasah esok hari.';const knownIds=[...document.querySelectorAll('[data-package-id]')].map(node=>node.dataset.packageId);if(data.packages.some(item=>!knownIds.includes(item.id))||knownIds.length!==data.packages.length)renderPackages(data.packages);['voters','voted','remaining'].forEach(id=>{const node=document.getElementById(id);const next=formatNumber(data[id]);if(node.textContent!==next){node.textContent=next;node.classList.remove('updated-flash');void node.offsetWidth;node.classList.add('updated-flash')}});document.getElementById('turnout').textContent=data.turnout+'%';data.packages.forEach(item=>{const card=document.querySelector(`[data-package-id="${item.id}"]`);if(!card)return;const voteNode=card.querySelector('[data-votes]'),nextVotes=Number(item.votes)||0,changed=Number(voteNode.dataset.value||0)!==nextVotes;voteNode.textContent=formatNumber(nextVotes);voteNode.dataset.value=nextVotes;card.querySelectorAll('[data-candidate-votes]').forEach(node=>node.textContent=formatNumber(nextVotes)+' suara paket');card.querySelector('[data-percentage]').textContent=item.percentage+'%';const bar=card.querySelector('.bar');bar.classList.toggle('has-value',nextVotes>0);card.querySelector('[data-bar]').style.width=item.percentage+'%';if(changed){card.classList.remove('vote-updated');void card.offsetWidth;card.classList.add('vote-updated');window.setTimeout(()=>card.classList.remove('vote-updated'),1150)}});reorderPackages(data.packages)}
async function refresh(){if(requestRunning)return;requestRunning=true;try{const response=await fetch(dataUrl,{headers:{Accept:'application/json'},cache:'no-store'});if(response.ok)updatePolling(await response.json())}catch(error){document.getElementById('liveLabel').textContent='MENGHUBUNGKAN'}finally{requestRunning=false}}
function tick(){const paused=phase==='paused',waiting=phase==='scheduled',target=waiting?startsAt:endsAt;document.getElementById('countdownLabel').innerHTML=`<i class="far fa-clock"></i> ${paused?'Voting dihentikan sementara':(waiting?'Pemungutan suara dimulai dalam':'Pemungutan suara berakhir dalam')}`;if(paused){document.getElementById('countdown').textContent='DIJEDA · MENUNGGU';return}if(!target){document.getElementById('countdown').textContent='-- : -- : --';return}const seconds=Math.max(0,Math.floor((new Date(target).getTime()-Date.now())/1000));const days=Math.floor(seconds/86400),hours=Math.floor(seconds%86400/3600),minutes=Math.floor(seconds%3600/60),secs=seconds%60;document.getElementById('countdown').textContent=(days?days+' HARI · ':'')+[hours,minutes,secs].map(v=>String(v).padStart(2,'0')).join(' : ')}
document.getElementById('fullscreenToggle').addEventListener('click',async()=>{if(!document.fullscreenElement){await document.documentElement.requestFullscreen?.()}else{await document.exitFullscreen?.()}});
tick();setInterval(tick,1000);setInterval(()=>{if(!document.hidden)refresh()},4000);
</script>
</body>
</html>
